from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]

p = ROOT/'backend/app/routers/debts.py'
t = p.read_text(encoding='utf-8')
if 'class DebtUpdate(BaseModel):' not in t:
    anchor='class DebtPaymentCreate(BaseModel):'
    if anchor not in t: raise SystemExit('ERROR: DebtPaymentCreate no encontrado')
    t=t.replace(anchor,'\nclass DebtUpdate(BaseModel):\n    creditor: str\n    debt_type: str\n    description: str | None = None\n    original_amount: Decimal\n    start_date: date\n    first_due_date: date | None = None\n    total_installments: int | None = None\n    installment_amount: Decimal | None = None\n    minimum_payment: Decimal | None = None\n    notes: str | None = None\n\n@router.patch("/{debt_id}")\ndef update_debt(debt_id: UUID, body: DebtUpdate):\n    if body.original_amount <= 0:\n        raise HTTPException(400, "El monto original debe ser mayor a cero")\n\n    n = body.total_installments or 1\n    if n < 1:\n        raise HTTPException(400, "La cantidad de cuotas debe ser al menos 1")\n\n    first = body.first_due_date or body.start_date\n    installment = money(body.installment_amount or (body.original_amount / n))\n\n    with db_cursor() as cur:\n        cur.execute(\n            sql.SQL("""\n                SELECT d.*,\n                       COALESCE((SELECT SUM(amount) FROM {}.debt_payments dp WHERE dp.debt_id=d.id),0) AS paid\n                FROM {}.debts d\n                WHERE d.id=%s\n                FOR UPDATE\n            """).format(S, S),\n            [debt_id],\n        )\n        debt = cur.fetchone()\n        if not debt:\n            raise HTTPException(404, "Deuda no encontrada")\n\n        paid = money(debt["paid"])\n        if body.original_amount < paid:\n            raise HTTPException(400, f"El monto original no puede ser menor que lo ya pagado ({paid})")\n\n        schedule_changed = (\n            money(body.original_amount) != money(debt["original_amount"])\n            or body.start_date != debt["start_date"]\n            or first != debt.get("first_due_date")\n            or n != int(debt.get("total_installments") or 1)\n            or installment != money(debt.get("installment_amount"))\n        )\n\n        if paid > 0 and schedule_changed:\n            raise HTTPException(\n                400,\n                "Esta deuda ya tiene pagos. Podés editar acreedor, tipo, descripción y notas, "\n                "pero no monto, fechas ni cuotas."\n            )\n\n        cur.execute(\n            sql.SQL("""\n                UPDATE {}.debts\n                SET creditor=%s,\n                    debt_type=%s,\n                    description=%s,\n                    original_amount=%s,\n                    start_date=%s,\n                    first_due_date=%s,\n                    total_installments=%s,\n                    installment_amount=%s,\n                    minimum_payment=%s,\n                    notes=%s,\n                    updated_at=now()\n                WHERE id=%s\n                RETURNING *\n            """).format(S),\n            [\n                body.creditor.strip(),\n                body.debt_type,\n                body.description,\n                money(body.original_amount),\n                body.start_date,\n                first,\n                n,\n                installment,\n                money(body.minimum_payment) if body.minimum_payment is not None else None,\n                body.notes,\n                debt_id,\n            ],\n        )\n        updated = cur.fetchone()\n\n        if paid <= 0 and schedule_changed:\n            cur.execute(sql.SQL("DELETE FROM {}.debt_installments WHERE debt_id=%s").format(S), [debt_id])\n            remaining = money(body.original_amount)\n            for i in range(1, n + 1):\n                amount = installment if i < n else remaining\n                amount = min(remaining, amount)\n                cur.execute(\n                    sql.SQL("""\n                        INSERT INTO {}.debt_installments\n                        (debt_id,installment_number,due_date,amount,status)\n                        VALUES (%s,%s,%s,%s,\'pendiente\')\n                    """).format(S),\n                    [debt_id, i, add_months(first, i - 1), amount],\n                )\n                remaining = max(Decimal("0"), remaining - amount)\n\n        return updated\n'+'\n'+anchor,1)
p.write_text(t,encoding='utf-8')

p = ROOT/'front/src/components/Modules.tsx'
t = p.read_text(encoding='utf-8')

old_state=" const [rows,setRows]=useState<any[]|null>(null),[summary,setSummary]=useState<any|null>(null),[accounts,setAccounts]=useState<any[]>([]),[error,setError]=useState(''),[open,setOpen]=useState(false),[pay,setPay]=useState<any|null>(null);"
new_state=" const [rows,setRows]=useState<any[]|null>(null),[summary,setSummary]=useState<any|null>(null),[accounts,setAccounts]=useState<any[]>([]),[error,setError]=useState(''),[open,setOpen]=useState(false),[pay,setPay]=useState<any|null>(null),[editDebt,setEditDebt]=useState<any|null>(null);"
if old_state not in t: raise SystemExit('ERROR: estado DebtManager no encontrado')
t=t.replace(old_state,new_state,1)

old_actions='<td><div className="row-actions">{r.status===\'activa\'&&Number(r.balance)>0&&<button className="mini-button" onClick={()=>setPay(r)}>Pagar</button>}<button className="mini-button danger-text" onClick={()=>remove(r)}>Eliminar</button></div></td>'
new_actions='<td><div className="row-actions">{r.status===\'activa\'&&Number(r.balance)>0&&<button className="mini-button" onClick={()=>setPay(r)}>Pagar</button>}<button className="mini-button" onClick={()=>setEditDebt(r)}>Editar</button><button className="mini-button danger-text" onClick={()=>remove(r)}>Eliminar</button></div></td>'
if old_actions not in t: raise SystemExit('ERROR: acciones DebtManager no encontradas')
t=t.replace(old_actions,new_actions,1)

old_tail='{open&&<DebtCreateModal accounts={accounts} close={()=>setOpen(false)} done={async()=>{setOpen(false);await load()}}/>}{pay&&<DebtPayModal debt={pay} accounts={accounts} close={()=>setPay(null)} done={async()=>{setPay(null);await load()}}/>}'
new_tail='{open&&<DebtCreateModal accounts={accounts} close={()=>setOpen(false)} done={async()=>{setOpen(false);await load()}}/>}{pay&&<DebtPayModal debt={pay} accounts={accounts} close={()=>setPay(null)} done={async()=>{setPay(null);await load()}}/>}{editDebt&&<DebtEditModal debt={editDebt} close={()=>setEditDebt(null)} done={async()=>{setEditDebt(null);await load()}}/>}'
if old_tail not in t: raise SystemExit('ERROR: modales DebtManager no encontrados')
t=t.replace(old_tail,new_tail,1)

if 'function DebtEditModal(' not in t:
    anchor='function FinanceSummary(){'
    if anchor not in t: raise SystemExit('ERROR: FinanceSummary no encontrado')
    t=t.replace(anchor,'\nfunction DebtEditModal({debt,close,done}:any){\n const [f,setF]=useState<any>({\n  creditor:debt.creditor||\'\',\n  debt_type:debt.debt_type||\'otra\',\n  description:debt.description||\'\',\n  original_amount:String(debt.original_amount??\'\'),\n  start_date:debt.start_date?String(debt.start_date).slice(0,10):new Date().toISOString().slice(0,10),\n  first_due_date:debt.first_due_date?String(debt.first_due_date).slice(0,10):\'\',\n  total_installments:String(debt.total_installments??1),\n  installment_amount:String(debt.installment_amount??\'\'),\n  minimum_payment:debt.minimum_payment==null?\'\':String(debt.minimum_payment),\n  notes:debt.notes||\'\'\n });\n const [saving,setSaving]=useState(false);\n const labels:any={tarjeta_credito:\'Tarjeta de crédito\',prestamo:\'Préstamo\',deuda_socio:\'Deuda con socio\',cheque_emitido:\'Cheque emitido\',cuota_vehiculo:\'Cuota vehículo / maquinaria\',impuesto_financiado:\'Impuesto financiado\',otra:\'Otra deuda\'};\n const hasPayments=Number(debt.paid_amount||0)>0;\n\n const submit=async()=>{\n  setSaving(true);\n  try{\n   await fetch(`${(process.env.NEXT_PUBLIC_API_URL||\'https://dirac-admin.onrender.com\').replace(/\\/$/,\'\')}/api/debts/${debt.id}`,{\n    method:\'PATCH\',\n    headers:{\'Content-Type\':\'application/json\',...(process.env.NEXT_PUBLIC_API_KEY?{\'X-API-Key\':process.env.NEXT_PUBLIC_API_KEY}:{})},\n    body:JSON.stringify({\n     creditor:String(f.creditor||\'\').trim(),\n     debt_type:f.debt_type,\n     description:String(f.description||\'\').trim()||null,\n     original_amount:Number(f.original_amount||0),\n     start_date:f.start_date,\n     first_due_date:f.first_due_date||null,\n     total_installments:Number(f.total_installments||1),\n     installment_amount:f.installment_amount===\'\'?null:Number(f.installment_amount),\n     minimum_payment:f.minimum_payment===\'\'?null:Number(f.minimum_payment),\n     notes:String(f.notes||\'\').trim()||null\n    })\n   }).then(async r=>{if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.detail||`Error ${r.status}`)}});\n   await done();\n  }catch(e:any){alert(e.message||String(e))}\n  finally{setSaving(false)}\n };\n\n return <div className="modal-backdrop"><div className="modal">\n  <div className="modal-head"><div><span className="eyebrow">EDITAR</span><h2>Editar deuda</h2></div><button className="close-button" onClick={close}>×</button></div>\n  {hasPayments&&<div className="modal-note" style={{marginBottom:14}}>Esta deuda ya tiene pagos. Para proteger la imputación, monto, fechas y cuotas no pueden modificarse.</div>}\n  <div className="form-grid">\n   <label className="field"><span>Acreedor *</span><input value={f.creditor} onChange={e=>setF({...f,creditor:e.target.value})}/></label>\n   <label className="field"><span>Tipo</span><select value={f.debt_type} onChange={e=>setF({...f,debt_type:e.target.value})}>{Object.entries(labels).map(([k,v]:any)=><option key={k} value={k}>{v}</option>)}</select></label>\n   <label className="field full"><span>Descripción</span><input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label>\n   <label className="field"><span>Monto original *</span><input disabled={hasPayments} type="number" min="0.01" step="0.01" value={f.original_amount} onChange={e=>setF({...f,original_amount:e.target.value})}/></label>\n   <label className="field"><span>Fecha inicio</span><input disabled={hasPayments} type="date" value={f.start_date} onChange={e=>setF({...f,start_date:e.target.value})}/></label>\n   <label className="field"><span>Primer vencimiento</span><input disabled={hasPayments} type="date" value={f.first_due_date} onChange={e=>setF({...f,first_due_date:e.target.value})}/></label>\n   <label className="field"><span>Cantidad de cuotas</span><input disabled={hasPayments} type="number" min="1" step="1" value={f.total_installments} onChange={e=>setF({...f,total_installments:e.target.value})}/></label>\n   <label className="field"><span>Monto cuota</span><input disabled={hasPayments} type="number" min="0" step="0.01" value={f.installment_amount} onChange={e=>setF({...f,installment_amount:e.target.value})}/></label>\n   <label className="field"><span>Pago mínimo</span><input type="number" min="0" step="0.01" value={f.minimum_payment} onChange={e=>setF({...f,minimum_payment:e.target.value})}/></label>\n   <label className="field full"><span>Notas</span><textarea rows={3} value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></label>\n  </div>\n  <div className="modal-actions"><button className="ghost-button" onClick={close}>Cancelar</button><button className="primary-button" disabled={saving||!String(f.creditor).trim()||Number(f.original_amount)<=0} onClick={submit}>{saving?\'Guardando…\':\'Guardar cambios\'}</button></div>\n </div></div>\n}\n'+'\n'+anchor,1)

p.write_text(t,encoding='utf-8')
print('OK: edición de deudas habilitada.')
